+::deep .btn-danger:hover {
+    background: #bb2d3b;
+}
+
+::deep .btn-small {
+    padding: 0.25rem 0.75rem;
+    font-size: 0.8rem;
+}
+
+::deep .toast {
+    margin-top: 1rem;
+    padding: 0.75rem 1rem;
+    border-radius: 0.375rem;
+    font-size: 0.9rem;
+}
+
+::deep .toast.success {
+    background: #d1e7dd;
+    color: #0f5132;
+    border: 1px solid #badbcc;
+}
+
+::deep .loading {
+    color: #6c757d;
+    font-style: italic;
+}
+
+/* Avatar */
+::deep .avatar-preview {
+    display: flex;
+    align-items: center;
+    gap: 1rem;
+    margin-bottom: 1.5rem;
+    padding: 1rem;
+    background: #f8f9fa;
+    border-radius: 0.5rem;
+}
+
+::deep .avatar-image {
+    width: 64px;
+    height: 64px;
+    border-radius: 50%;
+    object-fit: cover;
+    border: 2px solid #dee2e6;
+}
+
+::deep .avatar-url {
+    font-size: 0.8rem;
+    color: #6c757d;
+    word-break: break-all;
+}
+
+/* Toggles */
+::deep .toggle-group {
+    margin-bottom: 1.5rem;
+}
+
+::deep .toggle-row {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    padding: 0.5rem 0;
+    cursor: pointer;
+}
+
+::deep .toggle-row input[type="checkbox"] {
+    width: 1.1rem;
+    height: 1.1rem;
+}
+
+::deep .channel-list {
+    margin-top: 1.5rem;
+    padding-top: 1rem;
+    border-top: 1px solid #dee2e6;
+}
+
+::deep .channel-list h3 {
+    margin-bottom: 0.75rem;
+    font-size: 1.1rem;
+}
+
+/* Expandable panel */
+::deep .expandable-panel {
+    margin-bottom: 1.5rem;
+    border: 1px solid #dee2e6;
+    border-radius: 0.5rem;
+    overflow: hidden;
+}
+
+::deep .panel-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    width: 100%;
+    padding: 0.75rem 1rem;
+    background: #f8f9fa;
+    border: none;
+    cursor: pointer;
+    font-size: 1rem;
+    font-weight: 500;
+}
+
+::deep .panel-header:hover {
+    background: #e9ecef;
+}
+
+::deep .panel-body {
+    padding: 1rem;
+}
+
+::deep .error-message {
+    color: #dc3545;
+    font-size: 0.85rem;
+    margin-bottom: 0.75rem;
+}
+
+/* Two-Factor */
+::deep .twofa-section {
+    margin-bottom: 1.5rem;
+    padding: 1rem;
+    background: #f8f9fa;
+    border-radius: 0.5rem;
+}
+
+::deep .twofa-section h3 {
+    margin-bottom: 0.75rem;
+}
+
+::deep .status-row {
+    display: flex;
+    align-items: center;
+    gap: 1rem;
+}
+
+::deep .status-indicator.enabled {
+    color: #198754;
+    font-weight: 600;
+}
+
+::deep .status-indicator.disabled {
+    color: #dc3545;
+}
+
+::deep .info-text {
+    margin-top: 0.5rem;
+    font-size: 0.85rem;
+    color: #6c757d;
+}
+
+/* Sessions table */
+::deep .sessions-section {
+    margin-top: 1.5rem;
+}
+
+::deep .sessions-section h3 {
+    margin-bottom: 0.75rem;
+}
+
+::deep .sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+}
+
+::deep .sessions-table th,
+::deep .sessions-table td {
+    padding: 0.6rem 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #dee2e6;
+}
+
+::deep .sessions-table th {
+    background: #f8f9fa;
+    font-weight: 600;
+    font-size: 0.85rem;
+    text-transform: uppercase;
+    color: #6c757d;
+}
+
+::deep .current-badge {
+    font-size: 0.8rem;
+    color: #198754;
+    font-weight: 500;
+}
+
+/* Dialog */
+::deep .dialog-overlay {
+    position: fixed;
+    inset: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+::deep .dialog {
+    background: white;
+    padding: 1.5rem;
+    border-radius: 0.5rem;
+    max-width: 400px;
+    width: 90%;
+    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.2);
+}
+
+::deep .dialog h4 {
+    margin-bottom: 0.75rem;
+}
+
+::deep .dialog-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.25rem;
+    justify-content: flex-end;
+}
+
+/* Appearance radio groups */
+::deep .radio-group {
+    display: flex;
+    gap: 1.5rem;
+}
+
+::deep .radio-group label {
+    display: flex;
+    align-items: center;
+    gap: 0.375rem;
+    font-weight: normal;
+    cursor: pointer;
+}
+
+/* Preview area */
+::deep .preview-area {
+    margin-top: 1.5rem;
+    padding: 1.5rem;
+    border: 1px solid #dee2e6;
+    border-radius: 0.5rem;
+    transition: all 0.2s;
+}
+
+::deep .preview-area h4 {
+    margin-bottom: 0.5rem;
+}
+
+::deep .preview-badge {
+    display: inline-block;
+    margin-top: 0.75rem;
+    font-size: 0.8rem;
+    color: #6c757d;
+}
+
+::deep .preview-light {
+    background: #ffffff;
+    color: #212529;
+}
+
+::deep .preview-dark {
+    background: #1a1a2e;
+    color: #e0e0e0;
+    border-color: #333;
+}
+
+::deep .preview-dark .btn-primary {
+    background: #4a9eff;
+}
+
+::deep .preview-system {
+    background: #f0f0f0;
+    color: #333;
+}
+
+::deep .preview-small {
+    font-size: 0.8rem;
+}
+
+::deep .preview-medium {
+    font-size: 1rem;
+}
+
+::deep .preview-large {
+    font-size: 1.2rem;
+}
+
+::deep .preview-area.compact {
+    padding: 0.75rem;
+    line-height: 1.2;
+}
+

